using System;using System.Data;using System.Reflection;using System.Windows.Forms;using System.ComponentModel;
class Check{[STAThread]static void Main(){var a=Assembly.LoadFrom("work/Videira-3.7.exe");var st=a.GetType("Videira.Store");if(st==null){foreach(var x in a.GetTypes())if(x.Name=="Store")st=x;}string root=System.IO.Path.Combine(Environment.CurrentDirectory,"work","sort-check-"+Guid.NewGuid());var db=Activator.CreateInstance(st,new object[]{root});var data=(DataSet)st.GetField("Data").GetValue(db);var pt=data.Tables["Produtos"];foreach(var n in new[]{10,2,1}){var r=pt.NewRow();r["Id"]=n;r["Código"]=n.ToString();r["Nome"]="TESTE "+n;r["Estoque"]=1m;r["Ativo"]="Sim";r["Fornecedor"]="Teste";r["Custo"]=10m;r["Preço"]=20m;r["Confirmado"]=true;pt.Rows.Add(r);}Type ft=null;foreach(var x in a.GetTypes())if(x.Name=="MainForm")ft=x;var form=(Form)Activator.CreateInstance(ft,new object[]{db,false,""});form.Show();var flags=BindingFlags.Instance|BindingFlags.NonPublic;ft.GetMethod("ShowPage",flags).Invoke(form,new object[]{"Produtos"});var grid=(DataGridView)ft.GetField("grid",flags).GetValue(form);if(grid.Rows[0].Cells["Código"].Value.ToString()!="1"||grid.Rows[1].Cells["Código"].Value.ToString()!="2"||grid.Rows[2].Cells["Código"].Value.ToString()!="10")throw new Exception("Ordem numérica incorreta");grid.Sort(grid.Columns["Nome"],ListSortDirection.Descending);ft.GetMethod("RefreshGrid",flags).Invoke(form,null);if(grid.SortedColumn.Name!="Nome"||grid.SortOrder!=SortOrder.Descending)throw new Exception("Ordenação escolhida não preservada");form.Close();Console.WriteLine("PASS: códigos 1, 2, 10; ordenação por outra coluna preservada após atualizar.");}}

